js='''<script id="b2c-refresh-2026-js">(function(){const e=[...document.querySelectorAll('.b2cr-reveal')];if('IntersectionObserver'in window){const i=new IntersectionObserver(a=>a.forEach(x=>{if(x.isIntersecting){x.target.classList.add('is-visible');i.unobserve(x.target)}}),{threshold:.12});e.forEach(x=>i.observe(x))}else e.forEach(x=>x.classList.add('is-visible'));const s=[...document.querySelectorAll('.b2cr-slide')];let n=0;const show=x=>{n=(x+s.length)%s.length;s.forEach((z,j)=>z.classList.toggle('is-active',j===n))};document.querySelector('.b2cr-prev')?.addEventListener('click',()=>show(n-1));document.querySelector('.b2cr-next')?.addEventListener('click',()=>show(n+1));})();</script>'''

if 'b2c-refresh-2026' not in s:
    s=s.replace('</head>',css+'\n</head>',1)
else:
    s=re.sub(r'<style id="b2c-refresh-2026">.*?</style>',css,s,count=1,flags=re.S)
if not re.search(r'<main id="top".*?</main>',s,flags=re.S):
    raise SystemExit('Could not locate B2C main block')
s=re.sub(r'<main id="top".*?</main>',main,s,count=1,flags=re.S)
if 'b2c-refresh-2026-js' not in s:
    s=s.replace('</body>',js+'\n</body>',1)
p.write_text(s)
